INSERT INTO competencies (id, area_id, code, title, description, level, lapso)
VALUES
  ('comp-ini-ef4-1', 'ini-ef', 'CP-INI-EF4-01', 'Esquema Corporal y Equilibrio Dinámico', 'Reconoce los segmentos de su cuerpo a la voz de mando y mantiene el equilibrio postural sobre líneas rectas con variaciones de ritmo.', 'INICIAL', 1),
  ('comp-ini-ef4-2', 'ini-ef', 'CP-INI-EF4-02', 'Velocidad de Reacción y Saltabilidad en Circuitos', 'Ejecuta desplazamientos ágiles en zigzag y circuitos de saltos superando obstáculos con apoyo bipodal y unipodal.', 'INICIAL', 1)
INSERT INTO indicators (id, competency_id, area_id, code, description, level, lapso, evaluation_instrument)
VALUES
  ('ind-ini-ef4-101', 'comp-ini-ef4-1', 'ini-ef', 'IND-INI-EF4-1.1', 'Realiza equilibrio a través de una línea recta, con diferentes cambios de ritmo (caminando, trotando, corriendo).', 'INICIAL', 1, 'Escala de Estimación Cualitativa'),
  ('ind-ini-ef4-102', 'comp-ini-ef4-1', 'ini-ef', 'IND-INI-EF4-1.2', 'Reconoce todas sus partes del cuerpo a través de diferentes ejercicios a la voz del mando del profesor.', 'INICIAL', 1, 'Observación Directa'),
  ('ind-ini-ef4-201', 'comp-ini-ef4-2', 'ini-ef', 'IND-INI-EF4-2.1', 'Realiza de manera correcta la prueba de velocidad - reacción, desplazándose en zigzag por medio de unos conos.', 'INICIAL', 1, 'Escala de Estimación Cualitativa'),
  ('ind-ini-ef4-202', 'comp-ini-ef4-2', 'ini-ef', 'IND-INI-EF4-2.2', 'Ejecuta circuito de salto bipodal - unipodal, superando obstáculos en el camino de aros y mini vallas.', 'INICIAL', 1, 'Escala de Estimación Cualitativa')
INSERT INTO competencies (id, area_id, code, title, description, level, lapso)
VALUES
  ('comp-ini-ef5-1', 'ini-ef', 'CP-INI-EF5-01', 'Resistencia Aeróbica y Lateralidad Espacial', 'Dosifica su esfuerzo físico en intervalos continuos y ejecuta desplazamientos orientando su cuerpo hacia la izquierda y derecha.', 'INICIAL', 1),
  ('comp-ini-ef5-2', 'ini-ef', 'CP-INI-EF5-02', 'Circuitos Motrices Integrados y Coordinación Óculo-Manual', 'Supera circuitos de estaciones combinadas y manipula pelotas de diferentes tamaños en reposo y desplazamiento.', 'INICIAL', 1)
INSERT INTO indicators (id, competency_id, area_id, code, description, level, lapso, evaluation_instrument)
VALUES
  ('ind-ini-ef5-101', 'comp-ini-ef5-1', 'ini-ef', 'IND-INI-EF5-1.1', 'Realiza prueba de intervalo caminando - trotando por un tiempo estimado de 5 minutos.', 'INICIAL', 1, 'Escala de Estimación Cualitativa'),
  ('ind-ini-ef5-102', 'comp-ini-ef5-1', 'ini-ef', 'IND-INI-EF5-1.2', 'Ejecuta prueba de izquierda - derecha entre conos para proceder a saltar las mini vallas, aros y culminar con velocidad.', 'INICIAL', 1, 'Escala de Estimación Cualitativa'),
  ('ind-ini-ef5-201', 'comp-ini-ef5-2', 'ini-ef', 'IND-INI-EF5-2.1', 'Realiza de manera correcta el circuito motriz, en sus diferentes estaciones de: velocidad, reacción, salto bipodal – unipodal y zigzag.', 'INICIAL', 1, 'Escala de Estimación Cualitativa'),
  ('ind-ini-ef5-202', 'comp-ini-ef5-2', 'ini-ef', 'IND-INI-EF5-2.2', 'Trabaja la visión óculo manual correctamente con pelota pequeña / grande de forma estática y con movimiento.', 'INICIAL', 1, 'Escala de Estimación Cualitativa')
INSERT INTO competencies (id, area_id, code, title, description, level, lapso)
VALUES
  ('comp-ini-nat4-1', 'ini-nat', 'CP-INI-NAT4-01', 'Familiarización y Respiración Acuática Elemental', 'Adquiere seguridad y confianza en el medio acuático, ejecutando patadas desde el borde e inmersión buconasal con expulsión de burbujas bajo el agua.', 'INICIAL', 1),
  ('comp-ini-nat4-2', 'ini-nat', 'CP-INI-NAT4-02', 'Propulsión Asistida y Flotación Dorsal Inicial', 'Se desplaza en el agua mediante patada de estilo libre sujetando la tabla con apoyo docente y experimenta la flotación dorsal relajada.', 'INICIAL', 1)
INSERT INTO indicators (id, competency_id, area_id, code, description, level, lapso, evaluation_instrument)
VALUES
  ('ind-ini-nat4-101', 'comp-ini-nat4-1', 'ini-nat', 'IND-INI-NAT4-1.1', 'Se familiariza con el medio acuático, sintiéndose seguro(a) en el borde sentado(a), colocando los pies en punta para realizar patadas.', 'INICIAL', 1, 'Observación Directa Acuática'),
  ('ind-ini-nat4-102', 'comp-ini-nat4-1', 'ini-nat', 'IND-INI-NAT4-1.2', 'Realiza burbujitas de manera progresiva, tomando aire por la boca y expulsándolo por la nariz debajo del agua.', 'INICIAL', 1, 'Escala de Estimación Cualitativa'),
  ('ind-ini-nat4-201', 'comp-ini-nat4-2', 'ini-nat', 'IND-INI-NAT4-2.1', 'Se siente en confianza en tomar la tabla con las dos manos y con la ayuda del profesor realizar patada de libre con desplazamiento.', 'INICIAL', 1, 'Observación Directa Acuática'),
  ('ind-ini-nat4-202', 'comp-ini-nat4-2', 'ini-nat', 'IND-INI-NAT4-2.2', 'Se mantiene tranquilo(a) en flotación dorsal por unos segundos con la ayuda del profesor.', 'INICIAL', 1, 'Escala de Estimación Cualitativa')
INSERT INTO competencies (id, area_id, code, title, description, level, lapso)
VALUES
  ('comp-ini-nat5-1', 'ini-nat', 'CP-INI-NAT5-01', 'Propulsión Hidrodinámica y Nado de Flecha', 'Coordina la respiración continua con la patada propulsiva y adopta la posición hidrodinámica de flecha con cabeza sumergida hacia un objetivo.', 'INICIAL', 1),
