INSERT INTO indicators (id, competency_id, area_id, code, description, level, lapso, evaluation_instrument)
VALUES
  ('ind-ini-nat5-101', 'comp-ini-nat5-1', 'ini-nat', 'IND-INI-NAT5-1.1', 'Realiza burbujitas al mismo tiempo tomando la tabla para avanzar con la patada de libre con el acompañamiento del profesor.', 'INICIAL', 1, 'Escala de Estimación Cualitativa'),
  ('ind-ini-nat5-102', 'comp-ini-nat5-1', 'ini-nat', 'IND-INI-NAT5-1.2', 'Ejecuta el nado de flecha de manera eficiente, tomando en cuenta una mano encima de la otra, cabeza sumergida y patada constante, nadando hacia dirección del profesor.', 'INICIAL', 1, 'Observación Directa Acuática'),
  ('ind-ini-nat5-201', 'comp-ini-nat5-2', 'ini-nat', 'IND-INI-NAT5-2.1', 'Se siente seguro(a) y relajado(a) en hacer flotación dorsal abrazando la tabla, para luego hacerlo sin implemento.', 'INICIAL', 1, 'Escala de Estimación Cualitativa'),
  ('ind-ini-nat5-202', 'comp-ini-nat5-2', 'ini-nat', 'IND-INI-NAT5-2.2', 'Realiza la brazada del estilo libre con tabla, manteniendo la flotación horizontal y patada en movimiento alterna.', 'INICIAL', 1, 'Escala de Estimación Cualitativa')
INSERT INTO competencies (id, area_id, code, title, description, level, lapso)
