  ('ind-ini-inf4-102', 'comp-ini-inf4-1', 'ini-inf', 'IND-INI-INF4-1.2', 'Realiza clics simples y arrastra objetos en actividades digitales con apoyo mínimo.', 'INICIAL', 1, 'Registro de Destreza Digital'),
