  ('ind-ini-inf4-203', 'comp-ini-inf4-2', 'ini-inf', 'IND-INI-INF4-2.3', 'Participa activamente en actividades digitales, mostrando entusiasmo y atención sostenida.', 'INICIAL', 1, 'Registro Anecdótico Formativo')
INSERT INTO competencies (id, area_id, code, title, description, level, lapso)
VALUES
  ('comp-ini-inf5-1', 'ini-inf', 'CP-INI-INF5-01', 'Funcionalidad de Hardware, Coordinación Motriz y Navegación Autónoma', 'Explica la utilidad y función de los componentes del computador y pantallas táctiles, ejecuta clics dobles y arrastre con precisión visomotora y navega de forma independiente en entornos digitales.', 'INICIAL', 1),
