  ('ind-ini-inf5-103', 'comp-ini-inf5-1', 'ini-inf', 'IND-INI-INF5-1.3', 'Explora y navega de forma autónoma en juegos educativos digitales.', 'INICIAL', 1, 'Escala de Estimación Cualitativa'),
  ('ind-ini-inf5-201', 'comp-ini-inf5-2', 'ini-inf', 'IND-INI-INF5-2.1', 'Crea diseños y figuras utilizando herramientas de dibujo digital en Paint.', 'INICIAL', 1, 'Portafolio de Creaciones Digitales'),
  ('ind-ini-inf5-202', 'comp-ini-inf5-2', 'ini-inf', 'IND-INI-INF5-2.2', 'Reconoce íconos y herramientas básicas del programa Paint.', 'INICIAL', 1, 'Prueba Práctica de Interfaz'),
  ('ind-ini-inf5-203', 'comp-ini-inf5-2', 'ini-inf', 'IND-INI-INF5-2.3', 'Muestra iniciativa y creatividad al interactuar con recursos digitales.', 'INICIAL', 1, 'Rúbrica de Actitud y Creatividad Tecnológica')
INSERT INTO competencies (id, area_id, code, title, description, level, lapso)
